import "forge-std/Test.sol";
import "../src/CLEToken.sol";

contract LockTest is Test {
    CLEToken token;
    address owner = address(1);
    uint256 initialTime;

    function setUp() public {
        initialTime = block.timestamp;
        vm.warp(initialTime);
        vm.deal(owner, 100 ether);

        // Mock Uniswap router calls
        address router = address(0x05fF2B0DB69458A0750badebc4f9e13aDd608C7F);
        address factory = address(0x123);
        address WETH = address(0x456);

        // Mock router functions
        vm.mockCall(
            router,
            abi.encodeWithSignature("factory()"),
            abi.encode(factory)
        );
        vm.mockCall(
            router,
            abi.encodeWithSignature("WETH()"),
            abi.encode(WETH)
        );

        // Mock factory createPair
        vm.mockCall(
            factory,
            abi.encodeWithSignature("createPair(address,address)"),
            abi.encode(address(0x789))
        );

        // Deploy token contract with owner address
        vm.prank(owner);
        token = new CLEToken();
    }

    function test_owner_can_repeatedly_lock_contract() public {
        // Phase 1: Initial lock
        vm.prank(owner);
        token.lock(7 days);
        uint256 unlockTime1 = token.geUnlockTime();

        // Fast forward past initial lock period
        vm.warp(unlockTime1 + 1);

        // Unlock contract to regain ownership
        vm.prank(owner);
        token.unlock();

        // Phase 2: Immediate relock for longer period
        vm.prank(owner);
        token.lock(14 days);
        uint256 unlockTime2 = token.geUnlockTime();

        // Fast forward to end of second period
        vm.warp(unlockTime2 + 1);

        // Unlock again
        vm.prank(owner);
        token.unlock();

        // Phase 3: Final lock demonstrating repeated extendability
        vm.prank(owner);
        token.lock(30 days);
        uint256 finalUnlockTime = token.geUnlockTime();

        // Validate lock times show continuous extension
        assertGt(finalUnlockTime, unlockTime2, "Lock time not extended");
        assertGt(unlockTime2, unlockTime1, "Lock time not extended");
    }
}
